{"content": "1|//! Isometric renderer for CrabJar terrarium habitat.
2|//!
3|//! This module transforms the terrarium from ASCII art to isometric tile-based rendering.
4|//! Uses ANSI escape codes to draw diamond-shaped tiles that create a 3D isometric view.
5|
6|use std::io::{self, Write};
7|
8|// ============================================================================
9|// Constants
10|// ============================================================================
11|
12|const TILE_WIDTH: i32 = 8;   // Width of diamond in characters
13|const TILE_HEIGHT: i32 = 4;  // Height of diamond in characters
14|const SCREEN_WIDTH: i32 = 80;
15|const SCREEN_HEIGHT: i32 = 24;
16|
17|// ============================================================================
18|// Data Structures
19|// ============================================================================
20|
21|/// Tile type (ground, water, grass, etc.)
22|#[derive(Debug, Clone, Copy)]
23|pub enum TileType {
24|    Grass,
25|    Water,
26|    Sand,
27|    Stone,
28|    Wood,
29|}
30|
31|impl TileType {
32|    fn color(&self) -> &'static str {
33|        match self {
34|            TileType::Grass => "\x1b[32m",  // Green
35|            TileType::Water => "\x1b[36m",  // Cyan
36|            TileType::Sand => "\x1b[33m",   // Yellow
37|            TileType::Stone => "\x1b[90m",  // Gray
38|            TileType::Wood => "\x1b[95m",   // Purple
39|        }
40|    }
41|
42|    fn fg_color(&self) -> &'static str {
43|        match self {
44|            TileType::Grass => "\x1b[42m",
45|            TileType::Water => "\x1b[46m",
46|            TileType::Sand => "\x1b[43m",
47|            TileType::Stone => "\x1b[40m",
48|            TileType::Wood => "\x1b[45m",
49|        }
50|    }
51|}
52|
53|/// An isometric tile in the world
54|#[derive(Debug, Clone)]
55|pub struct IsometricTile {
56|    pub x: i32,      // Grid X coordinate
57|    pub y: i32,      // Grid Y coordinate
58|    pub z: i32,      // Height (for 3D effect)
59|    pub tile_type: TileType,
60|}
61|
62|/// Entity that moves on top of tiles (crab, snake, etc.)
63|#[derive(Debug, Clone)]
64|pub struct Entity {
65|    pub id: String,
66|    pub x: f32,      // Use floats for smooth movement
67|    pub y: f32,
68|    pub z: f32,
69|    pub symbol: &'static str,
70|    pub color: &'static str,
71|}
72|
73|/// Complete game world state
74|#[derive(Debug, Clone)]
75|pub struct GameWorld {
76|    pub tiles: Vec<IsometricTile>,
77|    pub entities: Vec<Entity>,
78|    pub tick: u64,
79|    pub paused: bool,
80|    pub speed: f32,
81|}
82|
83|// ============================================================================
84|// Isometric Projection Math
85|// ============================================================================
86|
87|/// Convert isometric grid coordinates to screen (terminal) coordinates.
88|/// 
89|/// Standard isometric projection formula:
90|/// - screen_x = (grid_x - grid_y) * tile_width / 2
91|/// - screen_y = (grid_x + grid_y) * tile_height / 4 - grid_z * tile_height / 2
92|fn to_screen_coords(x: i32, y: i32, z: i32) -> (i32, i32) {
93|    let screen_x = (x - y) * TILE_WIDTH / 2;
94|    let screen_y = (x + y) * TILE_HEIGHT / 4 - z * TILE_HEIGHT / 2;
95|    (screen_x, screen_y)
96|}
97|
98|/// Convert entity float coordinates to screen coordinates
99|fn to_screen_coords_f(x: f32, y: f32, z: f32) -> (i32, i32) {
100|    let ix = x as i32;
101|    let iy = y as i32;
102|    let iz = z as i32;
103|    to_screen_coords(ix, iy, iz)
104|}
105|
106|// ============================================================================
107|// Rendering Functions
108|// ============================================================================
109|
110|/// Draw a single diamond-shaped tile using ANSI escape codes.
111|fn draw_tile(tile: &IsometricTile, screen_x: i32, screen_y: i32) {
112|    let color = tile.tile_type.color();
113|    let fg_color = tile.tile_type.fg_color();
114|    let reset = "\x1b[0m";
115|
116|    // Move cursor to tile position
117|    print!("\x1b[{};{}H", screen_y + 2, screen_x + 2);
118|
119|    // Draw diamond using box-drawing characters
120|    // Top point
121|    print!("{} {}{}", color, "▲", reset);
122|    
123|    // Middle row (widest)
124|    print!("\x1b[{};{}H{}═══{}", screen_y + 3, screen_x + 1, color, reset);
125|    
126|    // Bottom point
127|    print!("\x1b[{};{}H{} {}{}", screen_y + 4, screen_x + 2, color, "▼", reset);
128|
129|    // Add height indicator (for 3D effect)
130|    if tile.z > 0 {
131|        for i in 0..tile.z {
132|            print!("\x1b[{};{}H│{}", fg_color, screen_y + 5 + i, reset);
133|        }
134|    }
135|}
136|
137|/// Draw an entity (crab, snake, etc.) at its position
138|fn draw_entity(entity: &Entity, screen_x: i32, screen_y: i32) {
139|    let reset = "\x1b[0m";
140|    
141|    print!("\x1b[{};{}H{}{}", screen_y + 2, screen_x + 2, entity.color, entity.symbol);
142|    print!("{}", reset);
143|}
144|
145|/// Clear the entire screen and move cursor to home position
146|fn clear_screen() {
147|    print!("\x1b[2J\x1b[H");
148|    io::stdout().flush().unwrap();
149|}
150|
151|/// Draw the entire world state
152|pub fn render_world(world: &GameWorld) {
153|    // Clear screen
154|    clear_screen();
155|
156|    // Render all tiles (sorted by z-height for proper depth ordering)
157|    let mut sorted_tiles = world.tiles.clone();
158|    sorted_tiles.sort_by_key(|t| t.z);
159|
160|    for tile in &sorted_tiles {
161|        let (screen_x, screen_y) = to_screen_coords(tile.x, tile.y, tile.z);
162|        draw_tile(tile, screen_x, screen_y);
163|    }
164|
165|    // Render all entities on top of tiles
166|    for entity in &world.entities {
167|        let (screen_x, screen_y) = to_screen_coords_f(entity.x, entity.y, entity.z);
168|        draw_entity(entity, screen_x, screen_y);
169|    }
170|
171|    // Draw HUD
172|    draw_hud(world);
173|
174|    io::stdout().flush().unwrap();
175|}
176|
177|/// Draw heads-up display with game info
178|fn draw_hud(world: &GameWorld) {
179|    let reset = "\x1b[0m";
180|    let pos = SCREEN_WIDTH - 20;
181|    
182|    print!("\x1b[{};{}H=== CRABJAR HABITAT ==={}", pos, 1, reset);
183|    print!("\x1b[{};{}HTick: {} | Speed: {:.1}x", pos, 3, world.tick, world.speed);
184|    print!("\x1b[{};{}HEntities: {}", pos, 4, world.entities.len());
185|    print!("\x1b[{};{}HControls: q=quit, Space=pause, +=speed, -=slow{}", pos, 6, reset);
186|}
187|
188|// ============================================================================
189|// World Generation
190|// ============================================================================
191|
192|/// Generate a simple isometric grid for the habitat
193|pub fn generate_world(width: i32, height: i32) -> GameWorld {
194|    let mut tiles = Vec::new();
195|    
196|    // Create a grid of grass tiles with some variety
197|    for x in 0..width {
198|        for y in 0..height {
199|            let tile_type = match (x + y) % 5 {
200|                0 => TileType::Water,
201|                1 => TileType::Grass,
202|                2 => TileType::Sand,
203|                3 => TileType::Stone,
204|                _ => TileType::Wood,
205|            };
206|            
207|            tiles.push(IsometricTile {
208|                x,
209|                y,
210|                z: 0,
211|                tile_type,
212|            });
213|        }
214|    }
215|
216|    // Add some elevated terrain (pyramids/structures)
217|    let mut elevated_tiles = vec![
218|        IsometricTile { x: 5, y: 5, z: 3, tile_type: TileType::Stone },
219|        IsometricTile { x: 10, y: 8, z: 2, tile_type: TileType::Wood },
220|        IsometricTile { x: 15, y: 5, z: 4, tile_type: TileType::Stone },
221|    ];
222|    
223|    tiles.append(&mut elevated_tiles);
224|
225|    // Add entities (crabs)
226|    let entities = vec![
227|        Entity {
228|            id: "crab_001".to_string(),
229|            x: 3.0,
230|            y: 3.0,
231|            z: 0.0,
232|            symbol: "🦀",
233|            color: "\x1b[91m",  // Red
234|        },
235|        Entity {
236|            id: "crab_002".to_string(),
237|            x: 7.0,
238|            y: 5.0,
239|            z: 0.0,
240|            symbol: "🦀",
241|            color: "\x1b[94m",  // Blue
242|        },
243|        Entity {
244|            id: "crab_003".to_string(),
245|            x: 12.0,
246|            y: 7.0,
247|            z: 0.0,
248|            symbol: "🦀",
249|            color: "\x1b[92m",  // Green
250|        },
251|    ];
252|
253|    GameWorld {
254|        tiles,
255|        entities,
256|        tick: 0,
257|        paused: false,
258|        speed: 1.0,
259|    }
260|}
261|
262|// ============================================================================
263|// Game Loop Integration
264|// ============================================================================
265|
266|/// Main render loop for isometric terrarium
267|pub async fn run_isometric_world(mut world: GameWorld) {
268|    eprintln!("DEBUG: isometric render loop STARTED");
269|    
270|    let mut tick = 0u64;
271|    while world.tick > 0 || tick == 0 {
272|        if !world.paused {
273|            // Update world state
274|            world.tick += 1;
275|            
276|            // Move entities smoothly (simple interpolation) with DAGR emission
277|            use crate::dagr_feed::{EventSource, EventType, GameEvent};
278|            use uuid::Uuid;
279|            for entity in &mut world.entities {
280|                let old_x = entity.x;
281|                let old_y = entity.y;
282|                // Simple wandering behavior
283|                entity.x += 0.05_f32 * world.speed;
284|                entity.y += 0.03_f32 * world.speed;
285|                
286|                // Wrap around screen edges
287|                if entity.x > SCREEN_WIDTH as f32 {
288|                    entity.x = 0.0;
289|                }
290|                if entity.y > (SCREEN_HEIGHT * 2) as f32 {
291|                    entity.y = 0.0;
292|                }
293|                
294|                // Emit DAGR event if entity moved
295|                if (entity.x - old_x).abs() > 0.001 || (entity.y - old_y).abs() > 0.001 {
296|                    let event = GameEvent {
297|                        id: Uuid::new_v4().to_string(),
298|                        event_type: EventType::EntityMove {
299|                            entity_id: entity.id.clone(),
300|                            from_x: old_x,
301|                            from_y: old_y,
302|                            to_x: entity.x,
303|                            to_y: entity.y,
304|                            direction: None,
305|                        },
306|                        timestamp: std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_secs(),
307|                        tick: world.tick,
308|                        source: EventSource::Simulation,
309|                        payload: crate::dagr_feed::EventPayload::EntityMove {
310|                            entity_id: entity.id.clone(),
311|                            from_x: old_x,
312|                            from_y: old_y,
313|                            to_x: entity.x,
314|                            to_y: entity.y,
315|                            direction: None,
316|                        },
317|                    };
318|                    eprintln!("DAGR EVENT: {}", serde_json::to_string(&event).unwrap_or_default());
319|                }
320|            }
321|            
322|            // Render frame
323|            render_world(&world);
324|        }
325|
326|        let sleep_ms = (50.0 / world.speed).max(10.0) as u64;
327|        tokio::time::sleep(tokio::time::Duration::from_millis(sleep_ms)).await; // speed-adjusted
328|    }
329|    
330|    eprintln!("DEBUG: isometric render loop EXITED");
331|}
332|
333|// ============================================================================
334|// Standalone Demo Mode
335|// ============================================================================
336|
337|/// Run a standalone demo without JSON-RPC control
338|pub fn run_demo() {
339|    let mut world = generate_world(20, 15);
340|    
341|    // Start animation immediately
342|    world.tick = 1;
343|    world.paused = false;
344|    
345|    eprintln!("🦀 CrabJar Isometric Habitat Demo");
346|    eprintln!("Press Ctrl+C to exit");
347|    
348|    tokio::runtime::Runtime::new()
349|        .unwrap()
350|        .block_on(run_isometric_world(world));
351|}
