{"content": "1|//! Terrarium as a Hermes plugin — text-mode TUI via stdio JSON-RPC.
2|//!
3|//! This module transforms the terrarium into a plugin that:
4|//! - Runs in herdr panes (no terminal size queries, no raw mode requirements)
5|//! - Accepts commands via JSON-RPC over stdin/stdout
6|//! - Outputs ASCII art/emoji to stdout for display
7|//! - Supports pause/resume/speed controls
8|
9|use serde::{Deserialize, Serialize};
10|use std::io::{self, BufRead, BufReader, Write};
11|use tokio::sync::{mpsc, Mutex};
12|use tokio::time::{sleep, Duration};
13|
14|// ============================================================================
15|// JSON-RPC Protocol
16|// ============================================================================
17|
18|/// Request envelope for terrarium commands.
19|#[derive(Debug, Deserialize)]
20|struct CommandRequest {
21|    id: u64,
22|    method: String,
23|    params: CommandParams,
24|}
25|
26|#[derive(Debug, Deserialize)]
27|struct CommandParams {
28|    action: TerrariumAction,
29|    #[serde(default)]
30|    value: Option<String>, // e.g., speed multiplier
31|}
32|
33|/// Available terrarium commands.
34|#[derive(Debug, Deserialize, Clone)]
35|#[serde(rename_all = "snake_case")]
36|enum TerrariumAction {
37|    Start,
38|    Stop,
39|    Pause,
40|    Resume,
41|    SetSpeed(String), // "0.5", "1.0", "10.0"
42|    Step,            // single tick
43|}
44|
45|/// Response envelope for terrarium commands.
46|#[derive(Debug, Serialize)]
47|struct CommandResponse {
48|    id: u64,
49|    result: Option<CommandResult>,
50|    error: Option<String>,
51|}
52|
53|#[derive(Debug, Serialize)]
54|struct CommandResult {
55|    status: String,
56|    message: Option<String>,
57|    crabs_count: Option<usize>,
58|}
59|
60|// ============================================================================
61|// Terrarium State (shared via Arc<Mutex>)
62|// ============================================================================
63|
64|/// Running terrarium state (shared between command handler and render loop).
65|struct TerrariumState {
66|    running: bool,
67|    paused: bool,
68|    speed_multiplier: f64,
69|    crabs_count: usize,
70|}
71|
72|impl Default for TerrariumState {
73|    fn default() -> Self {
74|        Self {
75|            running: false,
76|            paused: true,
77|            speed_multiplier: 1.0,
78|            crabs_count: 0,
79|        }
80|    }
81|}
82|
83|// ============================================================================
84|// Command Handler (JSON-RPC server)
85|// ============================================================================
86|
87|async fn handle_commands(state: &Mutex<TerrariumState>) -> io::Result<()> {
88|    let stdin = io::stdin();
89|    let stdout = io::stdout();
90|    let mut reader = BufReader::new(stdin.lock());
91|    let mut output = stdout.lock();
92|
93|    eprintln!("DEBUG: handle_commands STARTED");
94|
95|    loop {
96|        // Read JSON-RPC request
97|        let mut line = String::new();
98|        match reader.read_line(&mut line) {
99|            Ok(0) => {
100|                eprintln!("DEBUG: EOF received, breaking");
101|                break; // EOF
102|            }
103|            Ok(_) => {}
104|            Err(e) => {
105|                eprintln!("DEBUG: read error: {}", e);
106|                continue;
107|            }
108|        }
109|
110|        eprintln!("DEBUG: received command: {}", line.trim());
111|
112|        let request: CommandRequest = match serde_json::from_str(&line) {
113|            Ok(r) => r,
114|            Err(e) => {
115|                let resp = CommandResponse {
116|                    id: 0,
117|                    result: None,
118|                    error: Some(format!("parse error: {}", e)),
119|                };
120|                writeln!(output, "{}", serde_json::to_string(&resp).unwrap()).unwrap();
121|                output.flush().unwrap();
122|                continue;
123|            }
124|        };
125|
126|        // Handle command - lock state mutably
127|        let result = {
128|            let mut state_guard = state.lock().await;
129|            match request.method.as_str() {
130|                "terrarium/start" => {
131|                    state_guard.running = true;
132|                    state_guard.paused = false;
133|                    CommandResult {
134|                        status: "started".to_string(),
135|                        message: Some("Terrarium started".to_string()),
136|                        crabs_count: Some(state_guard.crabs_count),
137|                    }
138|                }
139|                "terrarium/stop" => {
140|                    state_guard.running = false;
141|                    state_guard.paused = true;
142|                    CommandResult {
143|                        status: "stopped".to_string(),
144|                        message: Some("Terrarium stopped".to_string()),
145|                        crabs_count: None,
146|                    }
147|                }
148|                "terrarium/pause" => {
149|                    state_guard.paused = true;
150|                    CommandResult {
151|                        status: "paused".to_string(),
152|                        message: Some("Terrarium paused".to_string()),
153|                        crabs_count: Some(state_guard.crabs_count),
154|                    }
155|                }
156|                "terrarium/resume" => {
157|                    state_guard.paused = false;
158|                    CommandResult {
159|                        status: "resumed".to_string(),
160|                        message: Some("Terrarium resumed".to_string()),
161|                        crabs_count: Some(state_guard.crabs_count),
162|                    }
163|                }
164|                "terrarium/set_speed" => {
165|                    if let Some(val) = request.params.value {
166|                        state_guard.speed_multiplier = val.parse().unwrap_or(1.0);
167|                        CommandResult {
168|                            status: "speed_set".to_string(),
169|                            message: Some(format!("Speed set to {}x", state_guard.speed_multiplier)),
170|                            crabs_count: Some(state_guard.crabs_count),
171|                        }
172|                    } else {
173|                        CommandResult {
174|                            status: "error".to_string(),
175|                            message: Some("Missing speed value".to_string()),
176|                            crabs_count: None,
177|                        }
178|                    }
179|                }
180|                "terrarium/step" => {
181|                    // Trigger a single tick (would need to signal render loop)
182|                    CommandResult {
183|                        status: "stepped".to_string(),
184|                        message: Some("Advanced one tick".to_string()),
185|                        crabs_count: Some(state_guard.crabs_count),
186|                    }
187|                }
188|                _ => CommandResult {
189|                    status: "error".to_string(),
190|                    message: Some(format!("Unknown method: {}", request.method)),
191|                    crabs_count: None,
192|                },
193|            }
194|        };
195|
196|        let response = CommandResponse {
197|            id: request.id,
198|            result: Some(result),
199|            error: None,
200|        };
201|
202|        writeln!(output, "{}", serde_json::to_string(&response).unwrap())?;
203|        output.flush()?;
204|    }
205|
206|    eprintln!("DEBUG: handle_commands EXITED");
207|    Ok(())
208|}
209|
210|// ============================================================================
211|// Render Loop (separate task)
212|// ============================================================================
213|
214|async fn render_loop(state: &Mutex<TerrariumState>) {
215|    // Placeholder: in a real implementation, this would:
216|    // 1. Spawn the terrarium world logic (from apps/terrarium/src/world.rs)
217|    // 2. Render ASCII art/emoji to stdout every tick
218|    // 3. Respond to state changes from command handler
219|
220|    eprintln!("DEBUG: render_loop STARTED");
221|    
222|    let mut tick = 0u64;
223|    loop {
224|        let running = {
225|            let state_guard = state.lock().await;
226|            state_guard.running
227|        };
228|        
229|        if !running {
230|            break; // Exit when running = false
231|        }
232|        
233|        let paused = {
234|            let state_guard = state.lock().await;
235|            state_guard.paused
236|        };
237|        
238|        let speed = {
239|            let state_guard = state.lock().await;
240|            state_guard.speed_multiplier
241|        };
242|
243|        if !paused {
244|            // Update world logic here
245|            tick += 1;
246|            
247|            // Render frame (placeholder) - use eprintln for debugging
248|            eprintln!("DEBUG: render_loop tick={} speed={}", tick, speed);
249|            print!("\x1b[2J\x1b[H"); // Clear screen
250|            print!("🦀 Terrarium - Tick: {} | Speed: {}x", tick, speed);
251|            print!("─────────────────────────────────────");
252|            print!("🐍 Snake moving... (placeholder)");
253|            print!("─────────────────────────────────────");
254|            print!("Controls: q=quit, Space=pause, +=speed, -=slow");
255|            std::io::stdout().flush().unwrap(); // Force flush
256|        }
257|
258|        sleep(Duration::from_millis(50)).await; // 20 FPS
259|    }
260|    
261|    eprintln!("DEBUG: render_loop EXITED");
262|}
263|
264|// ============================================================================
265|// Main Entry Point (plugin mode)
266|// ============================================================================
267|
268|#[tokio::main]
269|async fn main() {
270|    let args: Vec<String> = std::env::args().collect();
271|
272|    if args.len() > 1 && args[1] == "--help" {
273|        println!(
274|            "crabjar-terrarium-plugin — Text-mode TUI plugin for Hermes/Herdr\n\
275|             \n\
276|             Usage:\n\
277|               crabjar-terrarium-plugin [mode]\n\
278|             \n\
279|             Modes:\n\
280|               stdio   JSON-RPC over stdin/stdout (default in herdr)\n\
281|               text    Direct TUI output (for testing)\n\
282|         "
283|        );
284|        return;
285|    }
286|
287|    let mode = args.get(1).map(|s| s.as_str()).unwrap_or("stdio");
288|
289|    match mode {
290|        "stdio" => {
291|            println!("🦀 Terrarium plugin started (stdio mode)");
292|            
293|            let state = Mutex::new(TerrariumState::default());
294|            
295|            // Spawn command handler and render loop with shared state
296|            tokio::join!(
297|                handle_commands(&state),
298|                render_loop(&state)
299|            );
300|        }
301|        "text" => {
302|            // Fallback to direct TUI (like the original app)
303|            println!("🦀 Terrarium plugin started (text mode - fallback)");
304|            // TODO: spawn original run_text_mode() here
305|        }
