{"content": "1|//! Text-mode renderer for terrarium (herdr/standard terminal fallback)
2|
3|use ratatui::buffer::Buffer;
4|use ratatui::layout::Rect;
5|use ratatui::widgets::Widget;
6|
7|use super::world::{Crab, World};
8|
9|/// Text-mode renderer that works in any terminal (herdr, wezterm, etc.)
10|pub struct TextRenderer<'a> {
11|    world: &'a World,
12|}
13|
14|impl<'a> TextRenderer<'a> {
15|    pub fn new(world: &'a World) -> Self {
16|        Self { world }
17|    }
18|
19|    pub fn render(&self, frame: &mut Buffer, _body: Rect) -> crossterm::Result<()> {
20|        // Clear the buffer area
21|        for y in 0..frame.area().height {
22|            for x in 0..frame.area().width {
23|                if let Some(cell) = frame.cell_mut((x, y)) {
24|                    cell.set_char('.').set_style(
25|                        ratatui::style::Style::default()
26|                            .fg(ratatui::style::Color::Indexed(236)) // Light gray backdrop
27|                    );
28|                }
29|            }
30|        }
31|
32|        // Draw each crab as a colored glyph
33|        for crab in &self.world.crabs {
34|            let x = crab.pos_col as u16;
35|            let y = crab.pos_row as u16;
36|
37|            if x < frame.area().width && y < frame.area().height {
38|                if let Some(cell) = frame.cell_mut((x, y)) {
39|                    let fg = ratatui::style::Color::Rgb(crab.color[0], crab.color[1], crab.color[2]);
40|                    cell.set_char('🦀') // Crab emoji
41|                        .set_style(
42|                            ratatui::style::Style::default()
43|                                .fg(fg)
44|                                .add_modifier(ratatui::style::Modifier::BOLD)
45|                        );
46|                }
47|            }
48|        }
49|
50|        // Draw HUD at bottom
51|        let hud_y = frame.area().height.saturating_sub(3);
52|        
53|        // Line 1: Stats
54|        if let Some(cell) = frame.cell_mut((0, hud_y)) {
55|            cell.set_char(format!("🦀 Terrarium v0.1 | Crabs: {} | Ticks: {}", 
56|                self.world.crab_count(), self.world.ticks))
57|                .set_style(ratatui::style::Style::default().fg(ratatui::style::Color::Cyan));
58|        }
59|
60|        // Line 2: Controls
61|        if let Some(cell) = frame.cell_mut((0, hud_y + 1)) {
62|            cell.set_char("Controls: q=quit | Space=pause | +/- speed")
63|                .set_style(ratatui::style::Style::default().fg(ratatui::style::Color::Yellow));
64|        }
65|
66|        // Line 3: Status
67|        if let Some(cell) = frame.cell_mut((0, hud_y + 2)) {
68|            cell.set_char("Status: Running in text mode (no RGP)")
69|                .set_style(ratatui::style::Style::default().fg(ratatui::style::Color::Green));
70|        }
71|
72|        Ok(())
73|    }
74|}
