{"content": "1|//! The taste layer (spec §5) — parsed `behaviors.toml`.
2|//!
3|//! This is the "abstraction of the abstraction": a declarative assignment of
4|//! contract state to crab behavior. The renderer and the Phase-0 simulator
5|//! both consume a `Behaviors` value, so taste and code can never drift apart.
6|//! Unknown keys degrade gracefully (default behavior `wait`, default tint) —
7|//! a taste change never crashes the terrarium.
8|
9|use serde::Deserialize;
10|use std::collections::HashMap;
11|
12|/// Parsed `behaviors.toml`.
13|#[derive(Debug, Clone, Deserialize)]
14|pub struct Behaviors {
15|    #[serde(default)]
16|    pub schema_version: u32,
17|    /// effective_state → behavior name.
18|    #[serde(default)]
19|    pub behavior: HashMap<String, String>,
20|    /// evidence tier → certainty signal.
21|    #[serde(default)]
22|    pub evidence: HashMap<String, EvidenceSignal>,
23|    /// project id → habitat zone.
24|    #[serde(default)]
25|    pub zone: HashMap<String, Zone>,
26|    /// behavior → station marker (floor glyph + label).
27|    #[serde(default)]
28|    pub station: HashMap<String, Station>,
29|}
30|
31|#[derive(Debug, Clone, Deserialize)]
32|pub struct EvidenceSignal {
33|    pub tint: String,
34|    #[serde(default = "default_posture")]
35|    pub posture: String,
36|}
37|
38|#[derive(Debug, Clone, Deserialize)]
39|pub struct Zone {
40|    #[serde(default)]
41|    pub label: Option<String>,
42|    #[serde(default)]
43|    pub x: i32,
44|    #[serde(default)]
45|    pub y: i32,
46|}
47|
48|#[derive(Debug, Clone, Deserialize)]
49|pub struct Station {
50|    #[serde(default = "default_glyph")]
