{"content": "1|//! The behavior simulator — Phase 0 (spec §7).
2|//!
3|//! The load-bearing claim of the terrarium, made testable: the scene is a
4|//! **pure function** of `(run.json, behaviors.toml)`. No TUI, no terminal, no
5|//! global state. Given a contract and a taste, it produces the list of crabs
6|//! and what each one is doing. The TUI (Phase 1/2) is a *renderer* of this
7|//! output; the simulator is the interpreter.
8|//!
9|//! This is also the integration test for the whole concept: it runs against
10|//! the real `run.json` that `crabjar habitat contract` produces, so if the
11|//! producer and consumer ever drift on the wire, a test here fails.
12|
13|use crate::contract::{Run, Task};
14|use crate::mapping::Behaviors;
15|use std::collections::HashMap;
16|
17|/// What one crab is doing right now. The unit the renderer draws.
18|#[derive(Debug, Clone, PartialEq, Eq)]
19|pub struct Crab {
20|    /// The task id (crab identity is per-task, spec §9.3).
21|    pub id: String,
22|    /// The task's title (the crab's name plate).
23|    pub name: String,
24|    /// Derived effective state (spec §5): queued/running/review/done/failed/blocked.
25|    pub effective_state: String,
26|    /// The behavior the taste assigned to that state.
27|    pub behavior: String,
28|    /// Evidence tier of the latest attempt (drives the tint). Empty when none.
29|    pub evidence: String,
30|    /// Certainty tint from the taste (e.g. "amber").
31|    pub tint: String,
32|    /// Certainty posture from the taste (e.g. "neutral").
33|    pub posture: String,
34|    /// Shell age = latest attempt's `n` (1 = fresh shell). 0 when no attempt.
35|    pub shell_age: u32,
36|    /// The *why* — a failure's `reason` or a pass's `receipt`. The thought
37|    /// bubble. Never dropped (spec §5).
38|    pub note: Option<String>,
39|    /// Home zone id (the task's project, or "root").
40|    pub zone: String,
41|    /// Zone label from the taste.
42|    pub zone_label: String,
43|    /// Zone origin tile (isometric floor).
44|    pub zone_xy: (i32, i32),
45|    /// Floor glyph for the crab's station (from the taste).
46|    pub station_glyph: String,
47|}
48|
49|/// The full simulated habitat: every crab, plus the zone inventory and the
50|/// ambient tidings (from `events[]`) for the ticker.
51|#[derive(Debug, Clone, Default)]
52|pub struct Habitat {
53|    pub crabs: Vec<Crab>,
54|    /// zone id → label (for the zone legend).
55|    pub zones: HashMap<String, String>,
56|    /// Ambient narration, most-recent last (the contract is W207 time-ordered).
57|    pub tidings: Vec<String>,
58|}
59|
60|/// The one place state semantics live (spec §5). Derives the effective state
61|/// from a task and its latest attempt. The renderer and the simulator both
62|/// call this, so taste and code can never drift apart.
63|pub fn effective_state(task: &Task) -> String {
64|    // A blocked guard action always waves for a human, regardless of state.
65|    if task.needs_user {
66|        return "blocked".to_string();
67|    }
68|    let latest = task
69|        .attempts
70|        .iter()
71|        .max_by_key(|a| a.n.max(1))
72|        .or_else(|| task.attempts.last());
73|    match latest {
74|        Some(a) => match a.state.as_deref() {
75|            Some("running") => "running".to_string(),
76|            _ => match a.outcome.as_ref().and_then(|o| o.result.as_deref()) {
77|                Some("done" | "pass") => "done".to_string(),
78|                Some("failed" | "fail" | "error") => "failed".to_string(),
79|                // Settled but not a pass/fail verdict: awaiting judgment.
80|                _ => "review".to_string(),
81|            },
82|        },
83|        None => match task.state.as_deref() {
84|            Some("blocked") => "blocked".to_string(),
85|            Some(s) => s.to_string(),
86|            None => "queued".to_string(),
87|        },
88|    }
89|}
90|
91|/// The pure function. `(contract, taste) → habitat`. No I/O, no globals.
92|pub fn simulate(run: &Run, taste: &Behaviors) -> Habitat {
93|    let mut hab = Habitat::default();
94|
95|    for task in &run.tasks {
96|        let state = effective_state(task);
97|        let behavior = taste.behavior_for(&state).to_string();
98|
99|        let latest = task
100|            .attempts
101|            .iter()
102|            .max_by_key(|a| a.n.max(1))
103|            .or_else(|| task.attempts.last());
104|
105|        let (evidence, tint, posture, shell_age, note) = match latest {
106|            Some(a) => {
107|                let ev = a
108|                    .outcome
109|                    .as_ref()
110|                    .and_then(|o| o.evidence.clone())
111|                    .unwrap_or_default();
112|                let sig = taste.evidence_for(&ev);
113|                let note = a
114|                    .outcome
115|                    .as_ref()
116|                    .and_then(|o| o.reason.clone().or_else(|| o.receipt.clone()));
117|                (ev, sig.tint.clone(), sig.posture.clone(), a.n.max(1), note)
118|            }
119|            None => {
120|                let sig = taste.evidence_for("reported");
121|                (
122|                    String::new(),
123|                    sig.tint.clone(),
124|                    sig.posture.clone(),
125|                    0,
126|                    task.note.clone(),
127|                )
128|            }
129|        };
130|
131|        let (zone_id, zone) = taste.zone_for(task.project.as_deref());
132|        hab.zones
133|            .entry(zone_id.to_string())
134|            .or_insert_with(|| zone.label.clone().unwrap_or_else(|| zone_id.to_string()));
135|
136|        let station_glyph = taste.station_glyph(&behavior);
137|        hab.crabs.push(Crab {
138|            id: task.id.clone(),
139|            name: task.title.clone().unwrap_or_else(|| task.id.clone()),
140|            effective_state: state,
141|            behavior,
142|            evidence,
143|            tint,
144|            posture,
145|            shell_age,
146|            note,
147|            zone: zone_id.to_string(),
148|            zone_label: zone.label.clone().unwrap_or_else(|| zone_id.to_string()),
149|            zone_xy: (zone.x, zone.y),
150|            station_glyph,
151|        });
152|    }
153|
154|    // Ambient tidings from the event journal (already time-ordered, W207).
155|    for e in &run.events {
156|        if let (Some(at), Some(detail)) = (&e.at, &e.detail) {
157|            hab.tidings.push(format!("{at} {detail}"));
158|        }
159|    }
160|
161|    hab
162|}
