32|
33|impl TerrariumApp {
34|    pub fn new(contract_path: PathBuf, behaviors_path: Option<PathBuf>) -> Self {
35|        let run = Run::load(&contract_path).expect("contract load");
36|        let taste = match &behaviors_path {
37|            Some(p) => Behaviors::load(p),
38|            None => Behaviors::default(),
39|        };
40|        let habitat = simulator::simulate(&run, &taste);
41|        Self {
42|            contract_path,
43|            behaviors_path,
44|            run,
45|            taste,
46|            habitat,
47|            tidings_scroll: 0,
48|            running: true,
49|        }
50|    }
51|
52|    pub fn reload(&mut self) {
53|        let run = Run::load(&self.contract_path).expect("contract load");
54|        let taste = match &self.behaviors_path {
55|            Some(p) => Behaviors::load(p),
56|            None => Behaviors::default(),
57|        };
58|        self.run = run;
59|        self.taste = taste;
60|        self.habitat = simulator::simulate(&self.run, &self.taste);
61|    }
62|
63|    pub fn run(&mut self) -> Result<(), Box<dyn std::error::Error>> {
64|        enable_raw_mode()?;
65|        let mut stdout = std::io::stdout();
66|        execute!(stdout, EnterAlternateScreen)?;
67|        let backend = CrosstermBackend::new(stdout);
68|        let mut terminal = Terminal::new(backend)?;
69|
70|        let res = self.run_terminal(&mut terminal);
71|        disable_raw_mode()?;
72|        execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
73|        terminal.show_cursor()?;
74|        res
75|    }
76|
77|    fn run_terminal(
78|        &mut self,
79|        terminal: &mut Terminal<CrosstermBackend<std::io::Stdout>>,
80|    ) -> Result<(), Box<dyn std::error::Error>> {
81|        while self.running {
82|            terminal.draw(|f| self.ui(f))?;
83|            if event::poll(std::time::Duration::from_millis(50))? {
84|                if let Event::Key(key) = event::read()? {
85|                    if key.kind == KeyEventKind::Press {
86|                        match key.code {
87|                            KeyCode::Char('q') => self.running = false,
88|                            KeyCode::Char('r') => self.reload(),
89|                            KeyCode::Up | KeyCode::Char('k') => {
90|                                self.tidings_scroll = self.tidings_scroll.saturating_sub(1);
91|                            }
92|                            KeyCode::Down | KeyCode::Char('j') => {
93|                                self.tidings_scroll = self.tidings_scroll.saturating_add(1);
94|                            }
95|                            _ => {}
96|                        }
97|                    }
98|                }
99|            }
100|        }
101|        Ok(())
102|    }
103|
104|    fn ui(&mut self, f: &mut Frame) {
