146|pub struct IsometricView<'a> {
147|    pub habitat: &'a Habitat,
148|}
149|
150|impl ratatui::widgets::Widget for IsometricView<'_> {
151|    fn render(self, area: Rect, buf: &mut ratatui::buffer::Buffer) {
152|        let mut items: Vec<RenderItem> = Vec::new();
153|
154|        // Collect zones with positions from crab data
155|        for (zone_id, zone_label) in &self.habitat.zones {
156|            let mut origin_x = 0;
157|            let mut origin_y = 0;
158|            if let Some(first_crab) = self.habitat.crabs.iter().find(|c| c.zone == *zone_id) {
159|                origin_x = first_crab.zone_xy.0;
160|                origin_y = first_crab.zone_xy.1;
161|            }
162|            items.push(RenderItem::Zone {
163|                label: zone_label.clone(),
164|                origin_x,
165|                origin_y,
166|                depth: depth_key(origin_x, origin_y),
167|            });
168|        }
169|
170|        // Add crabs
171|        for crab in &self.habitat.crabs {
172|            items.push(RenderItem::Crab {
173|                crab: crab.clone(),
174|                depth: depth_key(crab.zone_xy.0, crab.zone_xy.1),
175|            });
176|        }
177|
178|        // Sort by depth (painter's algorithm)
179|        items.sort_by_key(|item| item.depth());
180|
181|        for item in &items {
182|            match item {
183|                RenderItem::Zone { label, origin_x, origin_y, .. } => {
184|                    let (col, row) = iso_transform(*origin_x, *origin_y, 2, 1);
185|                    if col < area.right() && row < area.bottom() {
186|                        buf[Rect::new(col, row, 1, 1)].set_char('┌');
187|                        buf[Rect::new(col, row, 1, 1)]
188|                            .set_style(Style::default().fg(Color::Cyan));
189|
190|                        if row > 0 {
191|                            let label_col = col.saturating_sub(label.len() as u16 / 2);
192|                            if label_col < area.right() && label_col + label.len() as u16 <= area.right() {
193|                                buf.set_string(label_col, row - 1, label.as_str(), Style::default().fg(Color::Cyan));
194|                            }
195|                        }
196|                    }
197|                }
198|                RenderItem::Crab { crab, .. } => {
199|                    let (col, row) = iso_transform(crab.zone_xy.0, crab.zone_xy.1, 2, 1);
200|
201|                    if col < area.right() && row < area.bottom() {
202|                        buf[Rect::new(col, row, 1, 1)].set_char('🦀');
203|                        buf[Rect::new(col, row, 1, 1)]
204|                            .set_style(style_for_tint(&crab.tint));
205|
206|                        if col + 1 < area.right() {
207|                            buf[Rect::new(col + 1, row, 1, 1)].set_char('🦀');
208|                            buf[Rect::new(col + 1, row, 1, 1)]
209|                                .set_style(style_for_tint(&crab.tint));
210|                        }
211|
212|                        if row + 1 < area.bottom() {
213|                            buf[Rect::new(col, row + 1, 1, 1)].set_char('🦀');
214|                            buf[Rect::new(col, row + 1, 1, 1)]
215|                                .set_style(style_for_tint(&crab.tint));
216|                        }
217|
218|                        if col + 1 < area.right() && row + 1 < area.bottom() {
219|                            let glyph = crab.station_glyph.chars().next().unwrap_or('▓');
220|                            buf[Rect::new(col + 1, row + 1, 1, 1)].set_char(glyph);
221|                        }
222|
223|                        if crab.shell_age > 0 && row > 0 {
224|                            let shell_text = format!("⌀{}", crab.shell_age);
225|                            let shell_col = col.saturating_sub(shell_text.len() as u16 / 2);
226|                            if shell_col < area.right() {
227|                                buf.set_string(shell_col, row - 1, shell_text.as_str(), Style::default().fg(Color::DarkGray));
228|                            }
229|                        }
230|
231|                        if let Some(note) = &crab.note {
232|                            if row > 1 {
233|                                let bubble = format!(" {}", truncate(note, 25));
234|                                let bubble_col = col.saturating_sub(bubble.len() as u16 / 2);
235|                                if bubble_col < area.right() && bubble_col + bubble.len() as u16 <= area.right() {
236|                                    buf.set_string(bubble_col, row - 2, bubble.as_str(), Style::default().fg(Color::White));
237|                                }
238|                            }
239|                        }
240|                    }
241|                }
242|            }
243|        }
244|    }
245|}
