247|#[derive(Clone)]
248|enum RenderItem {
249|    Zone {
250|        label: String,
251|        origin_x: i32,
252|        origin_y: i32,
253|        depth: i32,
254|    },
255|    Crab {
256|        crab: Crab,
257|        depth: i32,
258|    },
259|}
