261|impl RenderItem {
262|    fn depth(&self) -> i32 {
263|        match self {
264|            RenderItem::Zone { depth, .. } => *depth,
265|            RenderItem::Crab { depth, .. } => *depth,
266|        }
267|    }
268|}
