270|fn iso_transform(x: i32, y: i32, origin_col: u16, origin_row: u16) -> (u16, u16) {
271|    let screen_col = ((x - y) * 1) as u16 + origin_col;
272|    let screen_row = ((x + y) / 2) as u16 + origin_row;
273|    (screen_col, screen_row)
274|}
275|
276|fn depth_key(x: i32, y: i32) -> i32 {
277|    x + y
278|}
279|
280|fn style_for_tint(tint: &str) -> Style {
281|    match tint {
282|        "green" => Style::default().fg(Color::Green),
283|        "amber" => Style::default().fg(Color::Yellow),
284|        "orange" => Style::default().fg(Color::Rgb(255, 165, 0)),
285|        "gray" => Style::default().fg(Color::DarkGray),
286|        _ => Style::default().fg(Color::White),
287|    }
288|}
289|
290|fn truncate(s: &str, max: usize) -> String {
291|    if s.chars().count() <= max {
292|        s.to_string()
293|    } else {
294|        let t: String = s.chars().take(max.saturating_sub(1)).collect();
295|        format!("{}…", t)
296|    }
