{"content": "1|//! The terrarium CLI — Phase 1 (flat-grid TUI).
2|//!
3|//! `terrarium view` renders a ratatui TUI with zones as rows, crabs as single-glyph
4|//! + behavior verb, and a tidings ticker. Also watches for file changes.
5|
6|use clap::Parser;
7|use std::path::PathBuf;
8|
9|use terrarium::ui::TerrariumApp;
10|
11|#[derive(Parser)]
12|#[command(
13|    name = "terrarium",
14|    about = "An isometric hermit-crab skin over the crabjar habitat contract (dagr v3)."
15|)]
16|struct Cli {
17|    #[command(subcommand)]
18|    cmd: Cmd,
19|}
20|
21|#[derive(clap::Subcommand)]
22|enum Cmd {
23|    /// Render the simulated habitat from a contract file.
24|    View {
25|        /// Path to the dagr v3 contract (default: ./.dagr/run.json).
26|        #[arg(default_value = ".dagr/run.json")]
27|        contract: PathBuf,
28|        /// Path to the taste file (default: built-in taste).
29|        #[arg(long)]
30|        behaviors: Option<PathBuf>,
31|    },
32|}
33|
34|fn main() {
35|    let cli = Cli::parse();
36|    let code = match cli.cmd {
37|        Cmd::View { contract, behaviors } => run_view(&contract, behaviors.as_deref()),
38|    };
39|    std::process::exit(code);
40|}
41|
42|fn run_view(contract_path: &std::path::Path, behaviors_path: Option<&std::path::Path>) -> i32 {
43|    let mut app = TerrariumApp::new(
44|        contract_path.to_path_buf(),
45|        behaviors_path.map(|p| p.to_path_buf()),
46|    );
47|
48|    match app.run() {
49|        Ok(()) => 0,
50|        Err(e) => {
51|            eprintln!("TUI error: {}", e);
52|            1
53|        }
54|    }
