120|        let habitat = simulator::simulate(run, &taste);
121|
122|        // Create a large canvas to hold the isometric view (crabs can spread out significantly)
123|        // The iso transform formula (x-y)*1 and (x+y)/2 means we need room for both dimensions
124|        let area = Rect::new(0, 0, 160, 60);
125|        let mut buf = Buffer::empty(area);
126|
127|        // Render the IsometricView widget (we need to import this from ui module)
128|        use crate::ui::IsometricView;
129|        let view = IsometricView { habitat: &habitat };
130|        view.render(area, &mut buf);
