134|
135|    /// Assert that no two crabs occupy the same cell.
136|    ///
137|    /// This is the core finding #3 from the adversarial review: a small model can
138|    /// "fix" station offsets but stack multiple crabs on the same cell, which only
139|    /// human eyes would catch without this test.
140|    #[test]
141|    fn crabs_do_not_stack_on_same_cell() {
142|        let run = demo_contract();
143|        let buf = render_habitat(&run);
144|
